import * as api from './api.mjs';
import {initialState} from './seed.mjs';
import * as C from './core.mjs';

const app=document.getElementById('app'),modal=document.getElementById('modal'),toastEl=document.getElementById('toast');
let state=null,revision=0,role='',demo=false,route='home',selectedStudent='',dirty=false,saving=false,registerDate=C.today();
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>document.getElementById(id);const val=id=>byId(id)?.value??'';const qs=(q,r=document)=>r.querySelector(q);const qsa=(q,r=document)=>[...r.querySelectorAll(q)];
const currentDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const nav=[['home','⌂','My Homepage'],['students','◉','Students'],['attendance','✓','Attendance'],['behaviour','◆','Behaviour'],['tutors','▦','Tutor communities'],['classes','▤','Classes & timetables'],['exams','□','Exams'],['cover','↻','Cover'],['campus','⌖','Campus'],['school','!','School status'],['admin','⚙','Administration']];
function toast(msg,type='ok'){toastEl.textContent=msg;toastEl.className='show '+type;clearTimeout(toastEl._t);toastEl._t=setTimeout(()=>toastEl.className='',3500)}
function setDirty(v=true){dirty=v;const e=byId('saveState');if(e){e.disabled=!v||saving||demo;e.textContent=demo?'Demo mode':saving?'Saving…':v?'Save changes':'All changes saved'}}
function mutate(action,fn){try{fn();state.audit.unshift({id:C.uid(),date:new Date().toISOString(),action});setDirty();render();toast(action)}catch(e){toast(e.message,'bad')}}
async function save(action='Saved OneEducation workspace'){
 if(demo)return toast('Demo mode does not save. Sign in to use the live MIS.','bad');if(!dirty||saving)return;saving=true;setDirty(true);
 try{const r=await api.rpc('oe_save_state',{p_data:state,p_revision:revision,p_action:action});state=r.data;revision=Number(r.revision);role=r.role;dirty=false;toast('Changes saved to OneEducation.');}
 catch(e){toast(e.message,'bad');if(/REVISION_CONFLICT/.test(e.message))toast('Another staff member saved first. Refresh, then repeat your change.','bad')}
 finally{saving=false;setDirty(dirty)}
}
function showModal(title,body,wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<form method="dialog" class="modal-head"><h2>${esc(title)}</h2><button aria-label="Close dialog">×</button></form><div class="modal-body">${body}</div>`;modal.showModal();qs('input,select,textarea,button',modal)?.focus()}
function closeModal(){modal.close()}
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function selectOptions(items,selected='',label=x=>x.name){return items.map(x=>`<option value="${esc(x.id)}"${String(x.id)===String(selected)?' selected':''}>${esc(label(x))}</option>`).join('')}
function empty(title,copy=''){return `<div class="empty"><span>○</span><strong>${esc(title)}</strong>${copy?`<p>${esc(copy)}</p>`:''}</div>`}
function avatar(p){return `<span class="avatar">${esc(p.first[0]+p.last[0])}</span>`}
function name(p){return `${p.first} ${p.last}`}
function shell(content){
 const who=demo?'Demo administrator':api.identity()?.email||'Staff';
 app.innerHTML=`<div class="shell"><aside class="rail"><a class="logo" href="#home" data-route="home"><span></span><strong>one</strong><small>education</small></a><nav>${nav.map(([id,icon,label])=>`<a href="#${id}" data-route="${id}" class="${route===id?'active':''}" title="${esc(label)}"><b>${icon}</b><span>${esc(label)}</span></a>`).join('')}</nav><button id="collapseNav" title="Collapse navigation">‹</button></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" id="mobileMenu" aria-label="Open navigation">☰</button><div class="school-switch"><strong>Westview Secondary</strong><span>2026/27</span></div><label class="global-search"><span>⌕</span><input id="globalSearch" placeholder="Search students, groups and classes" autocomplete="off"><div id="searchResults"></div></label><div class="top-actions"><button title="Notifications">♢<i>${state.announcements.length}</i></button><div class="user"><span>${esc((who[0]||'O').toUpperCase())}</span><div><strong>${esc(who)}</strong><small>${esc(role||'admin')}</small></div></div><button id="signOut" title="Sign out">↗</button></div></header><main id="main">${content}</main><footer class="savebar"><span id="saveNote">${demo?'Viewing generated sample data. Changes remain on this device until refresh.':'Changes are checked for conflicts before saving.'}</span><button id="saveState" class="btn primary" ${demo||!dirty?'disabled':''}>${demo?'Demo mode':dirty?'Save changes':'All changes saved'}</button></footer></div></div>`;
 bindShell();
}
function bindShell(){
 qsa('[data-route]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();route=a.dataset.route;location.hash=route;render()}));
 byId('saveState')?.addEventListener('click',()=>save());byId('signOut')?.addEventListener('click',()=>{if(dirty&&!confirm('Sign out and discard unsaved changes?'))return;api.signOut();state=null;renderLogin()});
 byId('collapseNav')?.addEventListener('click',()=>qs('.shell').classList.toggle('nav-small'));byId('mobileMenu')?.addEventListener('click',()=>qs('.shell').classList.toggle('nav-open'));
 const search=byId('globalSearch'),results=byId('searchResults');search?.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();if(!q){results.innerHTML='';results.className='';return}const people=state.students.filter(p=>!p.archived&&`${name(p)} ${p.candidateNumber}`.toLowerCase().includes(q)).slice(0,6);const classes=state.classes.filter(c=>`${c.name} ${c.subject}`.toLowerCase().includes(q)).slice(0,4);results.innerHTML=[...people.map(p=>`<button data-person="${p.id}">${avatar(p)}<span><strong>${esc(name(p))}</strong><small>${esc(state.tutors.find(t=>t.id===p.tutorId)?.name||'')}</small></span></button>`),...classes.map(c=>`<button data-open-class="${c.id}"><span class="mini-icon">▤</span><span><strong>${esc(c.name)}</strong><small>${C.studentsIn(state,c.id).length} students</small></span></button>`)].join('')||'<p>No results</p>';results.className='open'});
 results?.addEventListener('click',e=>{const p=e.target.closest('[data-person]'),c=e.target.closest('[data-open-class]');if(p){selectedStudent=p.dataset.person;route='students';render()}if(c){route='classes';location.hash='classes';render();setTimeout(()=>showClass(c.dataset.openClass),0)}});
}
function renderLogin(){app.innerHTML=`<main class="login-page"><section class="login-brand"><div class="big-logo"><span></span><strong>one</strong><small>education</small></div><h1>School works better<br>when everything connects.</h1><p>Attendance, behaviour, timetables, exams and school communities for Westview Secondary.</p><div class="trust"><span>Secure staff access</span><span>Made by OneEducation</span></div></section><section class="login-panel"><form id="loginForm" class="login-card"><p class="eyebrow">WESTVIEW SECONDARY</p><h2>Sign in to your MIS</h2><p>Use your staff email and password.</p><label>Email address<input type="email" id="email" autocomplete="username" required value="${esc(window.ONEEDUCATION_CONFIG.adminEmail)}"></label><label>Password<input type="password" id="password" autocomplete="current-password" required></label><button class="btn primary" id="loginButton">Sign in</button><div class="form-status" id="loginStatus" role="status"></div><div class="login-sep"><span>or preview first</span></div><button type="button" class="btn soft" id="demoButton">Open interactive demo</button><a class="student-entry" href="student.html">Student &amp; family portal →</a></form><small class="made">OneEducation School Systems · Secure workspace</small></section></main>`;
 byId('loginForm').addEventListener('submit',async e=>{e.preventDefault();const b=byId('loginButton');b.disabled=true;b.textContent='Signing in…';try{const r=await api.signIn(val('email').trim(),val('password'));state=r.data||initialState();revision=Number(r.revision);role=r.role;if(!r.data){dirty=true;await save('Initialised Westview Secondary MIS')}demo=false;render()}catch(err){byId('loginStatus').textContent=err.message;byId('loginStatus').className='form-status bad';b.disabled=false;b.textContent='Sign in'}});
 byId('demoButton').addEventListener('click',()=>{state=initialState();revision=0;role='admin';demo=true;dirty=false;render()});
}
function pageHead(kicker,title,copy='',actions=''){return `<div class="page-head"><div><p>${esc(kicker)}</p><h1>${esc(title)}</h1>${copy?`<span>${esc(copy)}</span>`:''}</div><div class="page-actions">${actions}</div></div>`}
function stat(label,value,detail='',tone=''){return `<article class="stat ${tone}"><span>${esc(label)}</span><strong>${esc(value)}</strong>${detail?`<small>${esc(detail)}</small>`:''}</article>`}
function home(){
 const t=C.today(),closed=C.schoolClosed(state,t),present=state.attendance.filter(a=>a.date===t&&a.mark==='present').length,expected=state.attendance.filter(a=>a.date===t).length;const unresolved=state.incidents.filter(i=>i.status!=='resolved').length;
 const now=new Date();const wd=(now.getDay()+6)%7;const next=C.PERIODS.find(p=>typeof p.id==='number'&&C.mins(p.end)>now.getHours()*60+now.getMinutes());
 const greeting='Good '+(new Date().getHours()<12?'morning':'afternoon');
 return `${pageHead('MY HOMEPAGE',greeting,t,`<button class="btn soft" data-route="attendance">Take attendance</button><button class="btn primary" data-route="students">Add students</button>`)}
 ${closed?`<div class="closure-banner"><b>School ${esc(state.school.status)}</b><span>${esc(C.closureReason(state,t))} Registers are locked.</span><button data-route="school">Review status</button></div>`:''}
 <section class="dashboard-grid"><div class="stack"><div class="metrics">${stat('Attendance today',expected?Math.round(present/expected*100)+'%':'No marks','Across completed registers','green')}${stat('Students',String(state.students.filter(x=>!x.archived).length),'Current roll')}${stat('Behaviour follow-up',String(unresolved),'Open incidents',unresolved?'amber':'')}${stat('Cover today',String(state.covers.filter(c=>c.date===t).length),'Arrangements')}</div>
 <article class="card calendar-card"><div class="card-head"><div><p>MY CALENDAR</p><h2>Today at Westview</h2></div><span class="tag">${esc(C.DAYS[wd]||'Weekend')}</span></div>${wd>4?empty('No school lessons today'):C.PERIODS.map(p=>`<div class="agenda ${p===next?'current':''}"><time>${p.start}</time><span><strong>${esc(p.name)}</strong><small>${typeof p.id==='number'?'School timetable':'Non-teaching time'}</small></span>${p===next?'<b>Next</b>':''}</div>`).join('')}</article></div>
 <aside class="stack"><article class="card quick"><div class="card-head"><div><p>QUICK ACTIONS</p><h2>Get things done</h2></div></div><button data-route="attendance"><b>✓</b><span><strong>Take attendance</strong><small>Open a tutor or class register</small></span></button><button data-route="behaviour"><b>◆</b><span><strong>Log behaviour or praise</strong><small>Record points and removal</small></span></button><button data-route="cover"><b>↻</b><span><strong>Arrange cover</strong><small>Check teacher availability</small></span></button><button data-route="exams"><b>□</b><span><strong>Plan exams</strong><small>Mocks and official GCSE CSV</small></span></button></article>
 <article class="card notices"><div class="card-head"><div><p>SCHOOL NOTICES</p><h2>Latest updates</h2></div></div>${state.announcements.slice(-4).reverse().map(n=>`<div><span class="notice-dot"></span><p><strong>${esc(n.title)}</strong><small>${esc(n.body.split('\n')[0])}</small></p><time>${esc(C.nice(n.date))}</time></div>`).join('')||empty('No notices')}</article></aside></section>`;
}
function students(){
 const pupils=state.students.filter(p=>!p.archived);const selected=state.students.find(p=>p.id===selectedStudent&&!p.archived);
 if(selected)return studentProfile(selected);
 return `${pageHead('STUDENTS','Students',`${pupils.length} current students`,`<button class="btn soft" id="exportStudents">Export credentials CSV</button><button class="btn primary" id="openImport">Mass import</button>`)}<section class="card table-card"><div class="filters"><input id="studentFilter" placeholder="Search name or candidate number"><select id="studentYear"><option value="">All year groups</option>${[7,8,9,10,11].map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select><select id="studentTutor"><option value="">All tutor groups</option>${selectOptions(state.tutors)}</select></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Year</th><th>Tutor group</th><th>House</th><th>Set</th><th>Candidate no.</th><th></th></tr></thead><tbody id="studentRows">${pupils.map(studentRow).join('')}</tbody></table></div></section>`;
}
function studentRow(p){return `<tr data-student-row data-search="${esc(`${name(p)} ${p.candidateNumber}`.toLowerCase())}" data-year="${p.year}" data-tutor="${p.tutorId}"><td><button class="person-link" data-person="${p.id}">${avatar(p)}<span><strong>${esc(name(p))}</strong><small>Student</small></span></button></td><td>Year ${p.year}</td><td>${esc(state.tutors.find(t=>t.id===p.tutorId)?.name||'—')}</td><td><span class="house ${esc(p.house.toLowerCase())}">${esc(p.house)}</span></td><td>${esc(p.set)}</td><td><code>${esc(p.candidateNumber)}</code></td><td><button class="more" data-person="${p.id}" aria-label="View ${esc(name(p))}">›</button></td></tr>`}
function studentProfile(p){const tutor=state.tutors.find(t=>t.id===p.tutorId),points=state.points.filter(x=>x.studentId===p.id),score=points.reduce((n,x)=>n+(x.kind==='reward'?x.points:-x.points),0),date=C.today();const timetable=C.timetable(state,p,date);return `${pageHead('STUDENT PROFILE',name(p),`Year ${p.year} · ${tutor?.name||'No tutor'} · ${p.house} House`,`<button class="btn soft" id="backStudents">← Students</button><button class="btn primary" id="profileBehaviour">Record points</button>`)}<div class="profile-grid"><aside class="card profile-side">${avatar(p)}<h2>${esc(name(p))}</h2><span class="status-chip">Current student</span><dl><dt>Candidate number</dt><dd><code>${esc(p.candidateNumber)}</code></dd><dt>Student login code</dt><dd><code class="secret">${esc(p.loginCode||'Hidden for teacher accounts')}</code></dd><dt>Tutor group</dt><dd>${esc(tutor?.name||'—')}</dd><dt>House</dt><dd>${esc(p.house)}</dd><dt>Core set</dt><dd>${esc(p.set)}</dd></dl><button class="btn soft" id="copyCredentials" ${p.loginCode?'':'disabled'}>Copy login details</button>${role==='admin'?'<button class="text-danger" id="archiveStudent">Archive student</button>':''}</aside><div class="stack"><div class="metrics">${stat('Attendance',attendancePercent(p.id)+'%','Academic year')}${stat('Reward balance',String(score),'Net points',score>=0?'green':'amber')}${stat('Classes',String(p.classIds.length),'Current groups')}</div><article class="card"><div class="card-head"><div><p>TODAY</p><h2>Student timetable</h2></div><span class="tag">${esc(C.nice(date))}</span></div>${timetable.map(l=>`<div class="lesson ${l.removed?'removed':''} ${l.exam?'exam':''}"><time>${l.start}</time><div><strong>${l.removed?'Scheduled to be out of lesson':esc(l.subject)}</strong><small>${l.removed?'Behaviour removal':esc([l.className,l.room,l.teacher,l.cover?'Cover':'' ].filter(Boolean).join(' · '))}</small></div>${l.exam?'<span class="tag">Exam</span>':''}</div>`).join('')}</article><article class="card"><div class="card-head"><div><p>RECENT ACTIVITY</p><h2>Points and incidents</h2></div></div>${points.slice(-8).reverse().map(x=>`<div class="activity"><span class="${x.kind}">${x.kind==='reward'?'+':'−'}${x.points}</span><div><strong>${esc(x.reason)}</strong><small>${esc(C.nice(x.date))}${x.notes?' · '+esc(x.notes):''}</small></div></div>`).join('')||empty('No points recorded')}</article></div></div>`}
function attendancePercent(id){const a=state.attendance.filter(x=>x.studentId===id);return a.length?Math.round(a.filter(x=>['present','late'].includes(x.mark)).length/a.length*100):100}
function importDialog(){showModal('Mass import students',`<div class="step-grid"><label>Year group<select id="importYear">${[7,8,9,10,11].map(y=>`<option value="${y}"${y===11?' selected':''}>Year ${y}</option>`).join('')}</select></label><label>Tutor group<select id="importTutor"></select></label><label>Name order<select id="nameOrder"><option value="first-last">First name – Last name</option><option value="last-first">Last name – First name</option></select></label></div><label>Paste names or CSV<textarea id="importNames" rows="12" placeholder="First name,Last name&#10;Emma,Clarke&#10;Oliver,Patel"></textarea></label><p class="hint">OneEducation creates a random login code and candidate number, balances houses, assigns a core set and distributes Year 10/11 students across one GCSE option in each block.</p><div class="dialog-actions"><button class="btn soft" id="downloadTemplate">CSV template</button><button class="btn primary" id="reviewImport">Review import</button></div><div id="importResult"></div>`,true);fillTutorOptions();byId('importYear').addEventListener('change',fillTutorOptions);byId('downloadTemplate').addEventListener('click',()=>download('oneeducation-student-import-template.csv',C.csvWrite([['First name','Last name'],['Amelia','Example']])));byId('reviewImport').addEventListener('click',reviewImport)}
function fillTutorOptions(){const year=Number(val('importYear')),groups=state.tutors.filter(t=>t.year===year);byId('importTutor').innerHTML=groups.length?selectOptions(groups):'<option value="">No tutor groups for this year</option>'}
function reviewImport(){const parsed=C.parseNames(val('importNames'),val('nameOrder')),year=Number(val('importYear')),tutorId=val('importTutor'),box=byId('importResult');if(parsed.errors.length){box.innerHTML=`<div class="error-list"><strong>Fix these rows:</strong>${parsed.errors.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`;return}if(!parsed.names.length){box.innerHTML='<div class="error-list">Add at least one student.</div>';return}box.innerHTML=`<div class="review"><strong>${parsed.names.length} students ready for Year ${year}</strong><p>${esc(state.tutors.find(t=>t.id===tutorId)?.name||'No tutor selected')} · random credentials · balanced house and classes</p><div class="chips">${parsed.names.slice(0,12).map(n=>`<span>${esc(n.first+' '+n.last)}</span>`).join('')}${parsed.names.length>12?`<span>+${parsed.names.length-12} more</span>`:''}</div><button class="btn primary" id="confirmImport">Import students</button></div>`;byId('confirmImport').addEventListener('click',()=>{try{const r=C.importStudents(state,parsed.names,year,tutorId);state.audit.unshift({id:C.uid(),date:new Date().toISOString(),action:`Imported ${r.added.length} students`});setDirty();closeModal();render();showCredentials(r.added,r.skipped)}catch(e){box.innerHTML=`<div class="error-list">${esc(e.message)}</div>`}})}
function showCredentials(added,skipped=[]){showModal('Student logins created',`<p class="hint">Download this list now and store it securely. These codes give access to individual student information.</p><div class="credential-list">${added.map(p=>`<div>${avatar(p)}<span><strong>${esc(name(p))}</strong><small>${esc(state.tutors.find(t=>t.id===p.tutorId)?.name||'')} · Candidate ${esc(p.candidateNumber)}</small></span><code>${esc(p.loginCode)}</code></div>`).join('')}</div>${skipped.length?`<p>${skipped.length} duplicates were skipped.</p>`:''}<div class="dialog-actions"><button class="btn primary" id="downloadCredentials">Download secure CSV</button></div>`,true);byId('downloadCredentials').addEventListener('click',()=>download('student-login-codes.csv',C.csvWrite([['First name','Last name','Year','Tutor group','House','Set','Candidate number','Login code'],...added.map(p=>[p.first,p.last,p.year,state.tutors.find(t=>t.id===p.tutorId)?.name,p.house,p.set,p.candidateNumber,p.loginCode])]))) }
function attendance(){const closed=C.schoolClosed(state,registerDate),day=C.weekday(registerDate);return `${pageHead('ATTENDANCE','Registers',closed?'Attendance is locked because school is closed or closing.':'Choose a tutor group or lesson to open the register.',`<input type="date" id="registerDate" value="${registerDate}">`)}${closed?`<div class="closure-banner"><b>Registers locked</b><span>${esc(C.closureReason(state,registerDate))}</span><button data-route="school">School status</button></div>`:''}<div class="choice-grid"><article class="card"><p class="eyebrow">MORNING REGISTRATION</p><h2>Tutor groups</h2>${state.tutors.map(t=>`<button class="group-row" data-register="${t.id}" data-period="0"><span class="group-icon">${esc(t.name.slice(-3))}</span><span><strong>${esc(t.name)}</strong><small>Year ${t.year} · ${C.studentsIn(state,t.id).length} students</small></span><b>Open ›</b></button>`).join('')||empty('No tutor groups')}</article><article class="card"><p class="eyebrow">LESSON REGISTERS</p><h2>Teaching groups</h2>${state.classes.filter(c=>c.meetings.some(m=>m.day===day)).slice(0,18).map(c=>`<button class="group-row" data-register="${c.id}" data-period="${c.meetings.find(m=>m.day===day)?.period||1}"><span class="group-icon">${esc(c.subject.slice(0,2))}</span><span><strong>${esc(c.name)}</strong><small>${C.studentsIn(state,c.id).length} students · ${esc(state.teachers.find(t=>t.id===c.teacherId)?.name||'')}</small></span><b>Open ›</b></button>`).join('')||empty('No lessons on this date','Change the date to a school day.')}</article></div>`}
function registerDialog(groupId,period,date=val('registerDate')||currentDate()){const group=state.tutors.find(t=>t.id===groupId)||C.getClass(state,groupId),students=C.studentsIn(state,groupId);showModal(`${group?.name||'Register'} · ${C.PERIODS.find(p=>p.id===Number(period))?.name}`,`<div class="register-toolbar"><span>${esc(C.nice(date))}</span><button class="btn soft" id="markAllPresent">Mark all present</button></div><div class="register-list">${students.sort((a,b)=>a.last.localeCompare(b.last)).map(p=>{const saved=state.attendance.find(a=>a.studentId===p.id&&a.date===date&&a.period===Number(period));return `<article data-mark-row="${p.id}">${avatar(p)}<span><strong>${esc(p.last)}, ${esc(p.first)}</strong><small>${esc(state.tutors.find(t=>t.id===p.tutorId)?.name||'')} · ${esc(p.house)}</small></span><div class="mark-buttons">${[['present','✓','Present'],['absent','!','Absent'],['late','L','Late'],['ill','I','Ill'],['authorised','A','Authorised'],['medical','M','Medical']].map(([m,x,l])=>`<button class="${saved?.mark===m?'selected':''}" data-mark="${m}" title="${l}" aria-label="${l}">${x}</button>`).join('')}<button class="note ${saved?.notes?'has-note':''}" data-note title="Notes">⌄</button></div><textarea placeholder="Attendance notes" ${saved?.notes?'':'hidden'}>${esc(saved?.notes||'')}</textarea></article>`}).join('')||empty('No students in this group')}</div><div class="dialog-actions"><button class="btn primary" id="saveRegister" ${C.schoolClosed(state,date)?'disabled':''}>${C.schoolClosed(state,date)?'Register locked':'Save register'}</button></div>`,true);
 qsa('[data-mark-row]',modal).forEach(row=>{qsa('[data-mark]',row).forEach(b=>b.addEventListener('click',()=>{qsa('[data-mark]',row).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}));qs('[data-note]',row).addEventListener('click',()=>{const a=qs('textarea',row);a.hidden=!a.hidden;a.focus()})});byId('markAllPresent')?.addEventListener('click',()=>qsa('[data-mark="present"]',modal).forEach(b=>{qsa('[data-mark]',b.closest('article')).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}));byId('saveRegister')?.addEventListener('click',()=>{try{const marks=qsa('[data-mark-row]',modal).map(row=>({studentId:row.dataset.markRow,mark:qs('[data-mark].selected',row)?.dataset.mark||'present',notes:qs('textarea',row).value.trim()}));C.markAttendance(state,{date,period:Number(period),classId:groupId,marks});setDirty();closeModal();render();toast('Register recorded. Save changes to sync it.')}catch(e){toast(e.message,'bad')}})}
function behaviour(){return `${pageHead('BEHAVIOUR & REWARDS','Record and follow up','Points, incidents and removals are connected to attendance and student profiles.',`<button class="btn primary" id="newBehaviour">Record points</button>`)}<div class="metrics">${stat('Rewards this week',String(state.points.filter(p=>p.kind==='reward').reduce((n,x)=>n+x.points,0)),'House points','green')}${stat('Behaviour points',String(state.points.filter(p=>p.kind==='behaviour').reduce((n,x)=>n+x.points,0)),'Recorded')}${stat('Open incidents',String(state.incidents.filter(i=>i.status!=='resolved').length),'Needs follow-up','amber')}${stat('Removals',String(state.removals.length),'This workspace')}</div><section class="two-col"><article class="card"><div class="card-head"><div><p>RECENT ACTIVITY</p><h2>Behaviour timeline</h2></div></div>${state.points.slice(-12).reverse().map(x=>{const p=state.students.find(p=>p.id===x.studentId);return `<div class="activity"><span class="${x.kind}">${x.kind==='reward'?'+':'−'}${x.points}</span><div><strong>${esc(p?name(p):'Archived student')} · ${esc(x.reason)}</strong><small>${esc(C.nice(x.date))}${x.notes?' · '+esc(x.notes):''}</small></div></div>`}).join('')||empty('Nothing recorded yet')}</article><article class="card"><div class="card-head"><div><p>EMERGENCY & FOLLOW-UP</p><h2>Active concerns</h2></div></div>${state.incidents.slice(-10).reverse().map(i=>{const p=state.students.find(p=>p.id===i.studentId),t=state.tutors.find(t=>t.id===p?.tutorId);return `<article class="incident"><div><span>${esc(i.type)}</span><strong>${esc(t?.name||'No tutor')} · ${esc(p?name(p):'Archived student')}</strong><p>${esc(i.notes)}</p></div><button class="tag ${i.status==='resolved'?'green':''}" data-resolve="${i.id}">${esc(i.status)}</button></article>`}).join('')||empty('No active concerns')}</article></section>`}
function behaviourDialog(studentId=''){const pupils=state.students.filter(p=>!p.archived);showModal('Record behaviour or reward',`<div class="step-grid"><label>Student<select id="pointStudent"><option value="">Choose student</option>${selectOptions(pupils,studentId,name)}</select></label><label>Record type<select id="pointKind"><option value="reward">Reward / house points</option><option value="behaviour">Behaviour points</option><option value="removal">Behaviour removal</option><option value="emergency">Emergency / safeguarding response</option></select></label><label>Date<input id="pointDate" type="date" value="${C.today()}"></label></div><div id="pointFields"></div><div class="dialog-actions"><button class="btn primary" id="savePoint">Record</button></div>`);const renderFields=()=>{const kind=val('pointKind'),reasons=kind==='reward'?C.REASONS.reward:C.REASONS.behaviour;byId('pointFields').innerHTML=kind==='removal'?`<div class="step-grid"><label>Lesson<select id="removePeriod">${[1,2,3,4,5].map(n=>`<option value="${n}">Lesson ${n}</option>`).join('')}</select></label><label>Reason<input id="pointReason" value="Removal from lesson"></label></div><p class="hint">A removal in Lessons 1–3 schedules the student out of the current and next lesson. Lesson 4 stops at lunch; Lesson 5 affects Lesson 5 only.</p>`:kind==='emergency'?`<div class="step-grid"><label>Emergency type<select id="emergencyType"><option>Truancy</option><option>Missing student</option><option>Medical incident</option><option>Safeguarding concern</option><option>Serious behaviour</option><option>Site emergency</option></select></label><label>Status<select id="emergencyStatus"><option value="open">Open</option><option value="monitoring">Monitoring</option><option value="resolved">Resolved</option></select></label></div><label>Notes<textarea id="pointNotes" rows="5" required></textarea></label>`:`<div class="step-grid"><label>Reason<select id="pointReason">${reasons.map(([r,p])=>`<option value="${esc(r)}" data-points="${p}">${esc(r)} · ${p} points</option>`).join('')}</select></label><label>Points<input id="pointValue" type="number" min="1" max="50" value="${reasons[0][1]}"></label></div><label>Notes<textarea id="pointNotes" rows="4"></textarea></label>`;byId('pointReason')?.addEventListener('change',e=>{const o=e.target.selectedOptions?.[0];if(o?.dataset.points)byId('pointValue').value=o.dataset.points})};renderFields();byId('pointKind').addEventListener('change',renderFields);byId('savePoint').addEventListener('click',()=>{try{const studentId=val('pointStudent'),p=state.students.find(x=>x.id===studentId);if(!p)throw Error('Choose a student.');const kind=val('pointKind'),date=val('pointDate');if(kind==='removal'){C.removeFromLesson(state,studentId,date,Number(val('removePeriod')),val('pointReason').trim());state.points.push({id:C.uid(),studentId,kind:'behaviour',reason:val('pointReason').trim(),points:5,notes:`Removed during Lesson ${val('removePeriod')}`,date})}else if(kind==='emergency')state.incidents.push({id:C.uid(),studentId,type:val('emergencyType'),notes:val('pointNotes').trim(),status:val('emergencyStatus'),date});else state.points.push({id:C.uid(),studentId,kind,reason:val('pointReason'),points:Number(val('pointValue')),notes:val('pointNotes').trim(),date});setDirty();closeModal();render();toast('Student record updated.')}catch(e){toast(e.message,'bad')}})}
function tutors(){return `${pageHead('COMMUNITIES','Tutor groups','Tutor groups are student communities with announcements and a named tutor.',`<button class="btn primary" id="newTutor">Create tutor group</button>`)}<div class="tile-grid">${state.tutors.sort((a,b)=>a.name.localeCompare(b.name)).map(t=>`<article class="community"><div class="community-art"><span>${esc(t.name)}</span><small>YEAR ${t.year}</small></div><div><h2>${esc(t.name)}</h2><p>${esc(state.teachers.find(x=>x.id===t.teacherId)?.name||'No tutor')} · ${C.studentsIn(state,t.id).length}/${t.capacity} students</p><p>${esc(t.description||'Tutor community')}</p><button class="btn soft" data-community="${t.id}">Open community</button></div></article>`).join('')}</div>`}
function communityDialog(id){const t=state.tutors.find(t=>t.id===id),notices=state.announcements.filter(a=>a.scope==='tutor'&&a.groupId===id).reverse();showModal(t.name+' community',`<div class="community-summary"><span>${C.studentsIn(state,id).length} students</span><span>${esc(state.rooms.find(r=>r.id===t.roomId)?.name||'No room')}</span><span>${esc(state.teachers.find(x=>x.id===t.teacherId)?.name||'No tutor')}</span></div><label>Announcement title<input id="announcementTitle"></label><label>Message<textarea id="announcementBody" rows="5"></textarea></label><button class="btn primary" id="postAnnouncement">Post announcement</button><div class="community-feed">${notices.map(n=>`<article><small>${esc(C.nice(n.date))}</small><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></article>`).join('')||empty('No announcements yet')}</div>`,true);byId('postAnnouncement').addEventListener('click',()=>{if(!val('announcementTitle').trim()||!val('announcementBody').trim())return toast('Add a title and message.','bad');state.announcements.push({id:C.uid(),scope:'tutor',groupId:id,title:val('announcementTitle').trim(),body:val('announcementBody').trim(),date:C.today()});setDirty();closeModal();communityDialog(id);toast('Announcement added. Save to publish it.')})}
function classes(){return `${pageHead('SCHOOL STRUCTURE','Classes & timetables','Create a full year structure in one action, then assign students automatically.',`<button class="btn soft" id="generateTimetables">Generate timetables</button><button class="btn primary" id="classBuilder">Create classes</button>`)}<div class="metrics">${stat('Teaching groups',String(state.classes.length),'Across all years')}${stat('Teachers',String(state.teachers.length),'Generated and assigned')}${stat('Rooms',String(state.rooms.filter(r=>r.teaching).length),'Teaching spaces')}${stat('Scheduled meetings',String(state.classes.reduce((n,c)=>n+c.meetings.length,0)),'Weekly')}</div><section class="card table-card"><div class="filters"><input id="classFilter" placeholder="Search classes"><select id="classYear"><option value="">All years</option>${[7,8,9,10,11].map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Class</th><th>Subject</th><th>Year</th><th>Teacher</th><th>Students</th><th>Meetings</th><th></th></tr></thead><tbody id="classRows">${state.classes.sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<tr data-class-row data-search="${esc(`${c.name} ${c.subject}`.toLowerCase())}" data-year="${c.year}"><td><strong>${esc(c.name)}</strong><small>${c.kind==='option'?`GCSE block ${c.block}`:`Set ${c.set}`}</small></td><td>${esc(c.subject)}</td><td>Year ${c.year}</td><td>${esc(state.teachers.find(t=>t.id===c.teacherId)?.name||'—')}</td><td>${C.studentsIn(state,c.id).length}/${c.capacity}</td><td>${c.meetings.length}</td><td><button class="more" data-open-class="${c.id}">›</button></td></tr>`).join('')}</tbody></table></div></section>`}
function classBuilder(){const subjects=[...new Set([...Object.keys(C.KS3),...Object.keys(C.KS4),...Object.values(C.GCSE_BLOCKS).flat()])].sort();showModal('Create teaching groups',`<div class="step-grid"><label>Year<select id="buildYear">${[7,8,9,10,11].map(y=>`<option value="${y}"${y===11?' selected':''}>Year ${y}</option>`).join('')}</select></label><label>How many sets?<input id="buildSets" type="number" min="1" max="12" value="5"></label><label>Create<select id="buildMode"><option value="all">All core + GCSE subjects</option><option value="core">Core subjects only</option><option value="gcse">GCSE option subjects only</option><option value="single">One subject</option></select></label><label id="subjectWrap" hidden>Subject<select id="buildSubject">${subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><div class="info-panel"><strong>Automatic class naming</strong><p>Core sets use names like 11GM5 Maths. GCSE options create one class each, while History and Geography create A and B classes. Film Studies and Business are included.</p></div><div class="dialog-actions"><button class="btn primary" id="confirmBuild">Create classes</button></div>`);byId('buildMode').addEventListener('change',()=>byId('subjectWrap').hidden=val('buildMode')!=='single');byId('confirmBuild').addEventListener('click',()=>{try{const n=C.createClasses(state,{year:val('buildYear'),sets:val('buildSets'),mode:val('buildMode'),subject:val('buildSubject')});C.generateTimetables(state);setDirty();closeModal();render();toast(`${n} classes created and timetabled.`)}catch(e){toast(e.message,'bad')}})}
function showClass(id){const c=C.getClass(state,id),students=C.studentsIn(state,id),ann=state.announcements.filter(a=>a.scope==='class'&&a.groupId===id).reverse();showModal(c.name,`<div class="community-summary"><span>${esc(c.subject)}</span><span>Year ${c.year}</span><span>${students.length}/${c.capacity} students</span></div><div class="week-mini">${C.DAYS.map((d,i)=>`<div><strong>${d.slice(0,3)}</strong>${c.meetings.filter(m=>m.day===i).map(m=>`<span>P${m.period} · ${esc(state.rooms.find(r=>r.id===m.roomId)?.name||'No room')}</span>`).join('')}</div>`).join('')}</div><h3>Community announcements</h3>${ann.map(a=>`<article class="feed-item"><small>${esc(C.nice(a.date))}</small><strong>${esc(a.title)}</strong><p>${esc(a.body)}</p></article>`).join('')||empty('No announcements')}<h3>Students</h3><div class="chips">${students.map(p=>`<span>${esc(name(p))}</span>`).join('')||'<span>No students assigned</span>'}</div>`,true)}
function exams(){return `${pageHead('EXAMINATIONS','Exam centre','Plan mock weeks or import official GCSE dates into every matching class.',`<button class="btn soft" id="importExamCsv">Import official GCSE CSV</button><button class="btn primary" id="newExamCycle">Set exam dates</button>`)}<div class="metrics">${stat('Exam cycles',String(state.cycles.length),'Calendar windows')}${stat('Scheduled sittings',String(state.exams.length),'Across classes')}${stat('Official GCSE',String(state.exams.filter(e=>e.official).length),'CSV imported')}${stat('Mock sittings',String(state.exams.filter(e=>!e.official).length),'Generated')}</div><section class="two-col"><article class="card"><div class="card-head"><div><p>EXAM CALENDAR</p><h2>Cycles</h2></div></div>${state.cycles.map(c=>`<article class="cycle"><div><span class="tag ${c.type==='GCSE'?'green':''}">${esc(c.type)}</span><h3>Year ${c.year}</h3><p>${esc(C.nice(c.start))} – ${esc(C.nice(c.end))}</p></div><div><strong>${state.exams.filter(e=>e.cycleId===c.id).length}</strong><small>sittings</small>${c.type!=='GCSE'&&!state.exams.some(e=>e.cycleId===c.id)?`<button data-generate-mock="${c.id}">Generate</button>`:''}</div></article>`).join('')||empty('No exam cycles','Set the start and end dates first.')}</article><article class="card"><div class="card-head"><div><p>UPCOMING SITTINGS</p><h2>Exam timetable</h2></div></div>${state.exams.sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).slice(0,30).map(e=>{const c=C.getClass(state,e.classId);return `<div class="exam-row"><time>${esc(C.nice(e.date))}<small>${esc(e.start)}</small></time><div><strong>${esc(e.paper)}</strong><small>${esc(c?.name||'Class')} · ${esc(state.rooms.find(r=>r.id===e.roomId)?.name||'No room')}</small></div><span class="tag ${e.official?'green':''}">${e.official?'GCSE':'Mock'}</span></div>`}).join('')||empty('No exams scheduled')}</article></section>`}
function examCycleDialog(){showModal('Set exam dates',`<div class="step-grid"><label>Year<select id="cycleYear"><option value="10">Year 10</option><option value="11" selected>Year 11</option></select></label><label>Exam type<select id="cycleType"><option>Mock 1</option><option>Mock 2</option><option>Mock 3</option><option>GCSE</option></select></label><label>First exam<input id="cycleStart" type="date"></label><label>Last exam<input id="cycleEnd" type="date"></label></div><p class="hint">Mock 1 is Year 10 only. Mock 2, Mock 3 and GCSE are Year 11. Mock ranges must contain five school days. GCSE dates are filled by your official CSV.</p><button class="btn primary" id="saveCycle">Add to calendar</button>`);const sync=()=>{const type=val('cycleType');byId('cycleYear').value=type==='Mock 1'?'10':'11';byId('cycleYear').disabled=true};byId('cycleType').addEventListener('change',sync);sync();byId('saveCycle').addEventListener('click',()=>{try{C.createExamCycle(state,{year:val('cycleYear'),type:val('cycleType'),start:val('cycleStart'),end:val('cycleEnd')});setDirty();closeModal();render();toast('Exam cycle added to the calendar.')}catch(e){toast(e.message,'bad')}})}
function examImportDialog(){const cycles=state.cycles.filter(c=>c.type==='GCSE');showModal('Import official GCSE timetable',`<label>GCSE cycle<select id="csvCycle"><option value="">Choose cycle</option>${selectOptions(cycles,'',c=>`Year ${c.year} · ${C.nice(c.start)} to ${C.nice(c.end)}`)}</select></label><label>Official timetable CSV<input id="examFile" type="file" accept=".csv,text/csv"></label><p class="hint">Required columns: subject, paper, date, start_time, duration_minutes. Optional: board, class. Dates must be inside the selected GCSE calendar window.</p><button class="btn soft" id="examTemplate">Download template</button><button class="btn primary" id="reviewExams">Review CSV</button><div id="examReview"></div>`,true);byId('examTemplate').addEventListener('click',()=>download('official-gcse-timetable-template.csv',C.csvWrite([['subject','paper','date','start_time','duration_minutes','board','class'],['English Language','Paper 1','2027-05-24','09:00','105','AQA','']])));byId('reviewExams').addEventListener('click',async()=>{const f=byId('examFile').files[0],box=byId('examReview');if(!f)return box.innerHTML='<div class="error-list">Choose a CSV file.</div>';if(f.size>2*1024*1024)return box.innerHTML='<div class="error-list">CSV must be 2 MB or smaller.</div>';try{const result=C.parseOfficialCSV(state,await f.text(),val('csvCycle'));if(result.errors.length)box.innerHTML=`<div class="error-list"><strong>Fix these rows:</strong>${result.errors.slice(0,30).map(x=>`<p>${esc(x)}</p>`).join('')}</div>`;else{box.innerHTML=`<div class="review"><strong>${result.exams.length} class sittings ready</strong><p>Every matching class will receive an announcement.</p><button class="btn primary" id="confirmExams">Import official dates</button></div>`;byId('confirmExams').addEventListener('click',()=>{try{result.exams.forEach(e=>C.addExam(state,e));setDirty();closeModal();render();toast(`${result.exams.length} official GCSE sittings imported.`)}catch(e){toast(e.message,'bad')}})}}catch(e){box.innerHTML=`<div class="error-list">${esc(e.message)}</div>`}})}
function campus(){const rooms=state.rooms;return `${pageHead('SCHOOL SITE','Campus & rooms','Teaching spaces used by the automatic timetable.',`<button class="btn primary" id="newRoom">Add room</button>`)}<div class="campus-map"><section><div class="map-title"><strong>Westview campus</strong><span>${rooms.filter(r=>r.teaching).length} teaching rooms</span></div><div class="buildings">${[...new Set(rooms.map(r=>r.building))].map((b,i)=>`<article class="building b${i+1}"><h2>${esc(b)}</h2><p>${rooms.filter(r=>r.building===b).length} spaces</p><div>${rooms.filter(r=>r.building===b).slice(0,8).map(r=>`<span>${esc(r.code)}</span>`).join('')}</div></article>`).join('')}</div></section><aside class="card room-list"><p class="eyebrow">ALL ROOMS</p><h2>Spaces</h2>${rooms.map(r=>`<div><span class="room-code">${esc(r.code)}</span><p><strong>${esc(r.name)}</strong><small>${esc(r.type)} · ${r.teaching?'Teaching room':'Support space'}${r.capacity?' · '+r.capacity:''}</small></p></div>`).join('')}</aside></div>`}
function cover(){const date=currentDate();return `${pageHead('STAFFING','Cover arrangements','OneEducation checks the timetable before assigning a cover teacher.',`<button class="btn primary" id="newCover">Arrange cover</button>`)}<section class="card table-card"><div class="table-scroll"><table><thead><tr><th>Date</th><th>Lesson</th><th>Class</th><th>Usual teacher</th><th>Cover teacher</th><th>Reason</th></tr></thead><tbody>${state.covers.sort((a,b)=>a.date.localeCompare(b.date)).map(v=>{const c=C.getClass(state,v.classId);return `<tr><td>${esc(C.nice(v.date))}</td><td>Lesson ${v.period}</td><td><strong>${esc(c?.name||'—')}</strong></td><td>${esc(state.teachers.find(t=>t.id===c?.teacherId)?.name||'—')}</td><td>${esc(state.teachers.find(t=>t.id===v.teacherId)?.name||'—')}</td><td>${esc(v.reason)}</td></tr>`}).join('')||`<tr><td colspan="6">${empty('No cover arrangements')}</td></tr>`}</tbody></table></div></section>`}
function coverDialog(){showModal('Arrange lesson cover',`<div class="step-grid"><label>Date<input id="coverDate" type="date" value="${C.today()}"></label><label>Lesson<select id="coverPeriod">${[1,2,3,4,5].map(n=>`<option value="${n}">Lesson ${n}</option>`).join('')}</select></label><label>Class<select id="coverClass"></select></label><label>Cover teacher<select id="coverTeacher"></select></label></div><label>Reason<input id="coverReason" value="Staff absence"></label><button class="btn primary" id="saveCover">Save cover</button>`);const refresh=()=>{const date=val('coverDate'),period=Number(val('coverPeriod')),day=C.weekday(date),classes=state.classes.filter(c=>c.meetings.some(m=>m.day===day&&m.period===period));byId('coverClass').innerHTML=selectOptions(classes,'',c=>c.name);const classId=val('coverClass'),available=state.teachers.filter(t=>!C.teacherBusy(state,t.id,date,period,classId)&&t.id!==C.getClass(state,classId)?.teacherId);byId('coverTeacher').innerHTML=selectOptions(available,'',t=>t.name)};['coverDate','coverPeriod','coverClass'].forEach(id=>byId(id).addEventListener('change',refresh));refresh();byId('saveCover').addEventListener('click',()=>{try{C.addCover(state,{date:val('coverDate'),period:val('coverPeriod'),classId:val('coverClass'),teacherId:val('coverTeacher'),reason:val('coverReason').trim()});setDirty();closeModal();render();toast('Cover arrangement saved.')}catch(e){toast(e.message,'bad')}})}
function school(){return `${pageHead('SYSTEM','School status','Closing the school locks attendance and exam scheduling.',role==='admin'?`<button class="btn primary" id="changeStatus">Change status</button>`:'')}<section class="status-hero ${state.school.status}"><span>${state.school.status==='open'?'✓':'!'}</span><div><p>CURRENT STATUS</p><h2>Westview is ${esc(state.school.status)}</h2><strong>${esc(state.school.reason||'The normal school timetable and registers are active.')}</strong></div></section><div class="two-col"><article class="card"><div class="card-head"><div><p>CLOSURE CALENDAR</p><h2>Planned closures</h2></div>${role==='admin'?'<button class="btn soft" id="addClosure">Add closure</button>':''}</div>${state.closures.map(c=>`<div class="closure-row"><span>!</span><div><strong>${esc(c.reason)}</strong><small>${esc(C.nice(c.start))} – ${esc(C.nice(c.end))} · ${esc(c.status)}</small></div></div>`).join('')||empty('No planned closures')}</article><article class="card info-panel"><h2>What the lock changes</h2><ul><li>Staff cannot record attendance while the school is closed or closing.</li><li>Exam cycles cannot include closure dates.</li><li>Student timetables display the school status.</li><li>Saved historic attendance remains unchanged.</li></ul></article></div>`}
function admin(){return `${pageHead('ADMINISTRATION','OneEducation settings','Staff access, saved-data status and audit history.')}${role!=='admin'?'<div class="closure-banner"><b>Teacher access</b><span>Only administrators can change staff access or school structure.</span></div>':''}<div class="two-col"><article class="card"><div class="card-head"><div><p>STAFF ACCESS</p><h2>Authorised accounts</h2></div>${role==='admin'?'<button class="btn primary" id="manageAccess">Manage</button>':''}</div><div id="accessList"><p class="hint">Open Manage to load authorised accounts.</p></div></article><article class="card"><p class="eyebrow">DATA STATUS</p><h2>Workspace health</h2><dl class="health"><dt>Database revision</dt><dd>${revision}</dd><dt>Local unsaved changes</dt><dd>${dirty?'Yes':'No'}</dd><dt>Current role</dt><dd>${esc(role)}</dd><dt>Students</dt><dd>${state.students.filter(p=>!p.archived).length}</dd><dt>Last local action</dt><dd>${esc(state.audit[0]?.action||'None')}</dd></dl></article></div><article class="card audit-card"><div class="card-head"><div><p>AUDIT TRAIL</p><h2>Recent actions</h2></div></div><div id="auditList">${state.audit.slice(0,20).map(a=>`<div><time>${esc(new Date(a.date).toLocaleString('en-GB'))}</time><span>${esc(a.action)}</span></div>`).join('')||empty('No actions')}</div></article>`}
function render(){if(!state)return renderLogin();const views={home,students,attendance,behaviour,tutors,classes,exams,cover,campus,school,admin};shell((views[route]||home)());bindPage();setDirty(dirty)}
function bindPage(){
 qsa('main [data-route]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();route=x.dataset.route;location.hash=route;render()}));qsa('[data-person]').forEach(b=>b.addEventListener('click',()=>{selectedStudent=b.dataset.person;route='students';render()}));
 byId('openImport')?.addEventListener('click',importDialog);byId('exportStudents')?.addEventListener('click',()=>{const pupils=state.students.filter(p=>!p.archived);showCredentials(pupils)});byId('backStudents')?.addEventListener('click',()=>{selectedStudent='';render()});byId('profileBehaviour')?.addEventListener('click',()=>behaviourDialog(selectedStudent));byId('copyCredentials')?.addEventListener('click',async()=>{const p=state.students.find(x=>x.id===selectedStudent);await navigator.clipboard.writeText(`${name(p)}\nCandidate number: ${p.candidateNumber}\nLogin code: ${p.loginCode}\nPortal: ${new URL('student.html',location.href)}`);toast('Student login details copied.')});byId('archiveStudent')?.addEventListener('click',()=>{if(!confirm('Archive this student? They will be removed from current lists and their portal code will stop working.'))return;mutate('Archived '+name(state.students.find(x=>x.id===selectedStudent)),()=>state.students.find(x=>x.id===selectedStudent).archived=true);selectedStudent=''});
 const applyStudentFilters=()=>{const q=val('studentFilter').toLowerCase(),y=val('studentYear'),t=val('studentTutor');qsa('[data-student-row]').forEach(r=>r.hidden=!!(q&&!r.dataset.search.includes(q)||y&&r.dataset.year!==y||t&&r.dataset.tutor!==t))};['studentFilter','studentYear','studentTutor'].forEach(id=>byId(id)?.addEventListener('input',applyStudentFilters));
 qsa('[data-register]').forEach(b=>b.addEventListener('click',()=>registerDialog(b.dataset.register,b.dataset.period,registerDate)));byId('registerDate')?.addEventListener('change',()=>{registerDate=val('registerDate');render()});
 byId('newBehaviour')?.addEventListener('click',()=>behaviourDialog());qsa('[data-resolve]').forEach(b=>b.addEventListener('click',()=>mutate('Updated incident status',()=>{const i=state.incidents.find(x=>x.id===b.dataset.resolve);i.status=i.status==='resolved'?'open':'resolved'})));
 byId('newTutor')?.addEventListener('click',newTutorDialog);qsa('[data-community]').forEach(b=>b.addEventListener('click',()=>communityDialog(b.dataset.community)));
 byId('classBuilder')?.addEventListener('click',classBuilder);byId('generateTimetables')?.addEventListener('click',()=>mutate('Generated conflict-checked class timetables',()=>C.generateTimetables(state)));qsa('[data-open-class]').forEach(b=>b.addEventListener('click',()=>showClass(b.dataset.openClass)));const applyClassFilters=()=>{const q=val('classFilter').toLowerCase(),y=val('classYear');qsa('[data-class-row]').forEach(r=>r.hidden=!!(q&&!r.dataset.search.includes(q)||y&&r.dataset.year!==y))};['classFilter','classYear'].forEach(id=>byId(id)?.addEventListener('input',applyClassFilters));
 byId('newExamCycle')?.addEventListener('click',examCycleDialog);byId('importExamCsv')?.addEventListener('click',examImportDialog);qsa('[data-generate-mock]').forEach(b=>b.addEventListener('click',()=>mutate('Generated mock timetable',()=>C.generateMocks(state,b.dataset.generateMock))));
 byId('newCover')?.addEventListener('click',coverDialog);byId('newRoom')?.addEventListener('click',newRoomDialog);byId('changeStatus')?.addEventListener('click',statusDialog);byId('addClosure')?.addEventListener('click',closureDialog);byId('manageAccess')?.addEventListener('click',accessDialog);
}
function newTutorDialog(){showModal('Create tutor group',`<div class="step-grid"><label>Name<input id="tutorName" placeholder="10ABC"></label><label>Year<select id="tutorYear">${[7,8,9,10,11].map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select></label><label>Capacity<input id="tutorCapacity" type="number" min="1" max="50" value="32"></label><label>Tutor<select id="tutorTeacher">${selectOptions(state.teachers,'',t=>t.name)}</select></label><label>Base room<select id="tutorRoom">${selectOptions(state.rooms.filter(r=>r.teaching),'',r=>r.name)}</select></label></div><label>Community description<input id="tutorDescription" value="Tutor community"></label><button class="btn primary" id="saveTutor">Create group</button>`);byId('saveTutor').addEventListener('click',()=>{try{const n=val('tutorName').trim().toUpperCase(),y=Number(val('tutorYear'));if(!new RegExp(`^${y}[A-Z]{2,5}$`).test(n)||state.tutors.some(t=>t.name===n))throw Error('Use a unique name such as 10ABC matching the year.');state.tutors.push({id:C.uid(),name:n,year:y,capacity:Number(val('tutorCapacity')),teacherId:val('tutorTeacher'),roomId:val('tutorRoom'),description:val('tutorDescription').trim()});setDirty();closeModal();render();toast('Tutor community created.')}catch(e){toast(e.message,'bad')}})}
function newRoomDialog(){showModal('Add campus room',`<div class="step-grid"><label>Room code<input id="roomCode" placeholder="G25"></label><label>Name<input id="roomName" placeholder="G25"></label><label>Building<input id="roomBuilding" value="Learning block"></label><label>Type<select id="roomType">${['General','Science','Arts','Technology','Computing','PE','Exams','Office','Store'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Capacity<input id="roomCapacity" type="number" min="0" max="500" value="32"></label><label class="check"><input id="roomTeaching" type="checkbox" checked> Teaching room</label></div><button class="btn primary" id="saveRoom">Add room</button>`);byId('saveRoom').addEventListener('click',()=>{try{const code=val('roomCode').trim().toUpperCase();if(!code||state.rooms.some(r=>r.code===code))throw Error('Enter a unique room code.');state.rooms.push({id:C.uid(),code,name:val('roomName').trim()||code,building:val('roomBuilding').trim(),type:val('roomType'),capacity:Number(val('roomCapacity')),teaching:byId('roomTeaching').checked});setDirty();closeModal();render();toast('Room added.')}catch(e){toast(e.message,'bad')}})}
function statusDialog(){showModal('Change school status',`<label>Status<select id="schoolStatus"><option value="open"${state.school.status==='open'?' selected':''}>Open</option><option value="closing"${state.school.status==='closing'?' selected':''}>Closing</option><option value="closed"${state.school.status==='closed'?' selected':''}>Closed</option></select></label><label>Reason<textarea id="schoolReason" rows="4" placeholder="Severe weather, site issue, emergency…">${esc(state.school.reason)}</textarea></label><div class="warning">Changing to closing or closed immediately locks new attendance marks. Historic registers remain safe.</div><button class="btn primary" id="saveStatus">Update school status</button>`);byId('saveStatus').addEventListener('click',()=>{state.school.status=val('schoolStatus');state.school.reason=val('schoolReason').trim();setDirty();closeModal();render();toast('School status updated. Save changes to make it live.')})}
function closureDialog(){showModal('Add planned closure',`<div class="step-grid"><label>From<input id="closureStart" type="date"></label><label>To<input id="closureEnd" type="date"></label><label>Status<select id="closureStatus"><option value="closed">Closed</option><option value="closing">Closing</option></select></label></div><label>Reason<input id="closureReason" placeholder="INSET day or severe weather"></label><button class="btn primary" id="saveClosure">Add closure</button>`);byId('saveClosure').addEventListener('click',()=>{const start=val('closureStart'),end=val('closureEnd'),reason=val('closureReason').trim();if(!start||!end||start>end||!reason)return toast('Complete the dates and reason.','bad');state.closures.push({id:C.uid(),start,end,status:val('closureStatus'),reason});setDirty();closeModal();render();toast('Closure added to the calendar.')})}
async function accessDialog(){showModal('Manage staff access','<div class="loading">Loading authorised accounts…</div>',true);try{const list=await api.rpc('oe_staff_list');modal.querySelector('.modal-body').innerHTML=`<div class="access-list">${list.map(a=>`<div><span class="avatar">${esc(a.email[0].toUpperCase())}</span><p><strong>${esc(a.email)}</strong><small>${esc(a.role)}</small></p>${a.email!==window.ONEEDUCATION_CONFIG.adminEmail?`<button data-remove-staff="${esc(a.email)}">Remove</button>`:'<span class="tag green">Owner</span>'}</div>`).join('')}</div><hr><h3>Add or update staff</h3><div class="step-grid"><label>Verified Supabase user email<input id="staffEmail" type="email"></label><label>Role<select id="staffRole"><option value="teacher">Teacher</option><option value="admin">Administrator</option></select></label></div><button class="btn primary" id="saveAccess">Save access</button>`;byId('saveAccess').addEventListener('click',async()=>{try{await api.rpc('oe_set_staff',{p_email:val('staffEmail').trim(),p_role:val('staffRole')});toast('Staff access updated.');accessDialog()}catch(e){toast(e.message,'bad')}});qsa('[data-remove-staff]',modal).forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Remove this staff account from OneEducation?'))return;try{await api.rpc('oe_set_staff',{p_email:b.dataset.removeStaff,p_role:'remove'});toast('Staff access removed.');accessDialog()}catch(e){toast(e.message,'bad')}}))}catch(e){modal.querySelector('.modal-body').innerHTML=`<div class="error-list">${esc(e.message)}</div>`}}
window.addEventListener('beforeunload',e=>{if(dirty&&!demo){e.preventDefault();e.returnValue=''}});window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';render()});
route=location.hash.slice(1)||'home';renderLogin();

// Agent-accessible tools mirror visible, safe workflows where WebMCP is supported.
if(document.modelContext?.registerTool){
 document.modelContext.registerTool({name:'search_students',title:'Search students',description:'Search current Westview students by name or candidate number without changing data.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:({query})=>{if(!state)throw Error('Sign in first.');const q=String(query).trim().toLowerCase();return state.students.filter(p=>!p.archived&&`${name(p)} ${p.candidateNumber}`.toLowerCase().includes(q)).slice(0,20).map(p=>({id:p.id,name:name(p),year:p.year,tutor:state.tutors.find(t=>t.id===p.tutorId)?.name,candidateNumber:p.candidateNumber}))}});
 document.modelContext.registerTool({name:'open_attendance',title:'Open attendance',description:'Navigate the visible MIS to attendance registers. Does not record marks.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>{if(!state)throw Error('Sign in first.');route='attendance';location.hash=route;render();return{page:'attendance',schoolClosed:C.schoolClosed(state,C.today())}}});
}
